// PP 44/2015 art.19: upah sebulan is the contract's wage plus fixed allowances, a day's wage × 25, piece work its average.
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const unit = get(terms, 'rate.unit', 'MONTHLY');
const amount = Number(get(terms, 'rate.amount', 0));
const piece = unit === 'PIECE' || ['PIECE_RATE', 'TASK_BASIS'].includes(get(terms, 'statutory_work_category', ''));
const fixed = sum(
	Object.values(get(terms, 'allowances', {}))
		.filter((allowance) => get(allowance, 'variability', '') === 'FIXED')
		.map((allowance) => Number(get(allowance, 'amount', 0)))
);
const from = ctx.run.salary_coverage.from;
const yearStart = from.slice(0, 4) + '-01-01';
const started = get(employment, 'effective_range.from', yearStart);
const paidMonths = Number(from.slice(5, 7)) - Number((started > yearStart ? started : yearStart).slice(5, 7));
const paidWages = get(ctx.balances, 'ytd.ORDINARY_WAGES', 0);
const wage = () => {
	if (unit === 'HOURLY') return Number(get(ctx.subtotals, 'BASIC', 0)) + fixed;
	if (piece && paidMonths > 0 && paidWages > 0) return paidWages / paidMonths;
	if (piece) return Number(get(ctx.subtotals, 'ORDINARY_WAGES', 0));
	if (unit === 'DAILY') return amount * ctx.lookup.bpjs_daily_wage_days + fixed;
	return amount + fixed;
};
return round(Math.max(0, wage()) * ctx.lookup.employee_rate, ctx.lookup.whole_unit, 'HALF_UP');

