const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const facts = get(employment, 'employee_extension_data', {});
const unit = get(terms, 'rate.unit', 'MONTHLY');
// PMK 168/2023 art.1(11): paid only for the days, units or tasks worked.
const casual = ['DAILY', 'HOURLY', 'PIECE'].includes(unit) ||
	['PIECE_RATE', 'TASK_BASIS'].includes(get(terms, 'statutory_work_category', '')) ||
	get(employment, 'engagement', '') === 'PART_TIME';
const wages = Number(get(ctx.subtotals, 'ADDITIONAL_WAGES', 0));
const premiums =
	Number(get(ctx.statutory, 'JKK.employer', 0)) +
	Number(get(ctx.statutory, 'JKM.employer', 0)) +
	Number(get(ctx.statutory, 'KESEHATAN.employer', 0));
// art.5(3)(d)–(e) puts employer premiums in a permanent employee's income only.
const current = Math.max(0, casual ? wages : wages + premiums);
const surcharge = get(facts, 'tax_id_validated', true) === false ? ctx.lookup.missing_tax_id_multiplier : 1;
const periodEnd = String(get(get(ctx.run, 'salary_coverage', {}), 'to', ctx.as_of));
// balances close by pay date, so the tax year and its last period do too
const payDate = String(get(ctx.run, 'pay_date', ctx.as_of));
const taxYear = payDate.slice(0, 4);
const yearStart = taxYear + '-01-01';
const subjectFrom = String(get(facts, 'tax_subject_from', ''));
const subjectUntil = String(get(facts, 'tax_subject_until', ''));
const arrived = subjectFrom.slice(0, 4) === taxYear && subjectFrom.slice(5, 7) > '01';
const leaving = subjectUntil.slice(0, 4) === taxYear && subjectUntil.slice(5, 7) < '12';
// art.9(4)–(5): PTKP stands as at 1 January, or the first of a new resident's arrival month.
const standingDate = arrived ? month_start(subjectFrom) : yearStart;
const standings = get(facts, 'ptkp_standings', []).filter((row) => get(row, 'as_of', '') === standingDate);
if (standings.length > 1) throw 'Two PTKP standings on ' + standingDate + '.';
const standing = first(standings);
const marital = get(standing, 'marital_status', get(employment, 'payroll.marital_status', 'SINGLE'));
const gender = get(standing, 'gender', get(employment, 'payroll.gender', ''));
const husband = get(standing, 'husband_no_income_certified', get(facts, 'husband_no_income_certified', false)) === true;
const marriedFemale = marital === 'MARRIED' && gender === 'FEMALE' && !husband;
const dependents = Math.min(
	Math.max(0, Math.trunc(Number(get(standing, 'ptkp_dependents_count', get(facts, 'ptkp_dependents_count', 0))))),
	ctx.lookup.maximum_dependants
);
const status = marriedFemale ? 'TK/0' : (marital === 'MARRIED' ? 'K/' : 'TK/') + String(dependents);
const table = get(ctx.lookup, 'ter_' + get(ctx.lookup.ptkp_ter_table, status, '1'), []);
// PMK 168/2023 art.5(1): the month's gross is all its regular and irregular pay, so a month's runs are one month of income.
const heldMonth = get(ctx, 'balances.month', {});
const before = (code) => {
	const key = payDate.slice(0, 7) + '.' + code;
	return Object.hasOwn(heldMonth, key) ? Number(heldMonth[key]) : 0;
};
const monthGross =
	current +
	before('ADDITIONAL_WAGES') +
	(casual ? 0 : before('JKK.employer') + before('JKM.employer') + before('KESEHATAN.employer'));
const monthly = Math.max(
	0,
	round(bracket(monthGross, table) * monthGross * surcharge, ctx.lookup.whole_unit, 'HALF_UP') - before('PPH21.employee')
);
const cadence = get(facts, 'pph21_payment_cadence', 'MONTHLY');
// arts.12(2), 16(2): no non-permanent worker has a year-end reckoning.
if (casual && cadence === 'MONTHLY') return monthly;
if (casual) {
	const worked = get(ctx, 'work.days', []).filter((day) => get(day, 'worked', false) === true).length;
	const rate = Number(get(terms, 'rate.amount', 0));
	const paidDays = unit === 'DAILY' && rate > 0 ? Number(get(ctx.subtotals, 'BASIC', 0)) / rate : 1;
	const days = worked > 0 ? worked : Math.max(1, paidDays);
	const perDay = current / days;
	if (perDay <= ctx.lookup.daily_ter_ceiling)
		return round(bracket(perDay, ctx.lookup.ter_daily) * current * surcharge, ctx.lookup.whole_unit, 'HALF_UP');
	return round(ladder(perDay * ctx.lookup.daily_taxable_share, ctx.lookup.annual_ladder) * days * surcharge, ctx.lookup.whole_unit, 'HALF_UP');
}
const exit = get(employment, 'effective_range.to', null);
// December reckons the year on its salary: an off-cycle run ahead of that salary is not the last period.
const december = payDate.slice(5, 7) === '12' && (get(ctx.run, 'kind', '') !== 'OFF_CYCLE' || before('ORDINARY_WAGES') > 0);
const last = december || (exit != null && exit <= periodEnd) || (leaving && subjectUntil <= periodEnd);
if (!last) return monthly;
const ptkp = ctx.lookup.ptkp_amount[status];
const employedFrom = get(employment, 'effective_range.from', yearStart);
const joined = employedFrom > yearStart ? employedFrom : yearStart;
const opening = arrived && subjectFrom > joined ? subjectFrom : joined;
const closing = [exit, leaving ? subjectUntil : null].reduce(
	(end, date) => (date != null && date < end ? date : end),
	payDate
);
const months = Math.min(
	12,
	Math.max(
		1,
		(Number(closing.slice(0, 4)) - Number(opening.slice(0, 4))) * 12 +
			Number(closing.slice(5, 7)) -
			Number(opening.slice(5, 7)) +
			1
	)
);
const paid = (code) => {
	const held = get(ctx.balances, 'statutory_contribution', {});
	return Object.hasOwn(held, code) ? held[code] : 0;
};
const annualGross =
	Number(get(ctx.balances, 'ytd.ADDITIONAL_WAGES', 0)) +
	paid('JKK.employer') +
	paid('JKM.employer') +
	paid('KESEHATAN.employer') +
	current;
const expense = Math.min(
	annualGross * ctx.lookup.employment_expense_share,
	ctx.lookup.monthly_employment_expense_limit * months
);
const contributions =
	paid('JHT.employee') +
	paid('JP.employee') +
	Number(get(ctx.statutory, 'JHT.employee', 0)) +
	Number(get(ctx.statutory, 'JP.employee', 0));
const ownDeductions = (Number(get(facts, 'dplk_employee_monthly', 0)) + Number(get(facts, 'zakat_monthly', 0))) * months;
const net = annualGross - expense - contributions - ownDeductions;
// art.15(3): a part-year resident's net income is annualised and the tax taken back to the months.
const partYear = arrived || leaving;
const partMonths = (leaving ? Number(subjectUntil.slice(5, 7)) : 12) - (arrived ? Number(subjectFrom.slice(5, 7)) : 1) + 1;
const taxable = Math.max(0, (partYear ? (net * 12) / partMonths : net) - ptkp);
const yearTax = ladder(round(taxable, ctx.lookup.thousand_units, 'DOWN'), ctx.lookup.annual_ladder);
const due = round((partYear ? (yearTax * partMonths) / 12 : yearTax) * surcharge, ctx.lookup.whole_unit, 'HALF_UP');
const withheld = paid('PPH21.employee');
// art.21(1)–(2): the excess goes back, never the part the government bore.
if (due >= withheld) return due - withheld;
return -Math.min(withheld - due, withheld - paid('PPH21_DTP.employer'));

